commits.content:
.cart-success-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 9999;
}

.cart-success-card {
  width: 380px;
  background: #fff;
  padding: 40px;
  border-radius: 14px;
  text-align: center;
  animation: scaleIn 0.4s ease;
}

@keyframes scaleIn {
  from {
    transform: scale(0.7);
    opacity: 0;
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}

.success-icon {
  width: 80px;
  height: 80px;
  margin: 0 auto 20px;
  background: #ff9800;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  animation: pulse 1.5s infinite;
}

.success-icon i {
  color: #fff;
  font-size: 32px;
}

.success-icon .check {
  position: absolute;
  bottom: -6px;
  right: -6px;
  width: 26px;
  height: 26px;
  background: #4caf50;
  color: #fff;
  border-radius: 50%;
  font-size: 14px;
  display: flex;
  justify-content: center;
  align-items: center;
}

@keyframes pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(255, 152, 0, 0.6);
  }
  70% {
    box-shadow: 0 0 0 15px rgba(255, 152, 0, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(255, 152, 0, 0);
  }
}

.success-actions {
  display: flex;
  gap: 12px;
  margin-top: 25px;
}

.btn-primary {
  flex: 1;
  background: #ff9800;
  color: #fff;
  border: none;
  padding: 12px;
  border-radius: 6px;
  cursor: pointer;
}

.btn-outline {
  flex: 1;
  background: #fff;
  border: 1px solid #ddd;
  padding: 12px;
  border-radius: 6px;
  cursor: pointer;
}
